from pathlib import Path
out=Path('public/assets')
products=[('semaglutide','SEMAGLUTIDE','Weight care','#cbded1','#eaf2e9','#277362','vial'),('tirzepatide','TIRZEPATIDE','Weight care','#d7cce5','#eee7f3','#745594','vial'),('metformin','METFORMIN','Metabolic health','#edc9b3','#f7e6d9','#a05b37','bottle'),('nad','NAD+','Cellular health','#d9e4a9','#f2f4d9','#718044','vial'),('sermorelin','SERMORELIN','Healthy aging','#b8d7e0','#e4eff2','#477484','vial'),('hair-growth','HAIR GROWTH','Daily essentials','#e9c2cb','#f7e5e9','#9b5364','bottle')]
for handle,name,desc,bg,light,ink,kind in products:
 bottle=kind=='bottle'
 capy=126 if bottle else 164; bodyy=174 if bottle else 207; bodyh=260 if bottle else 224
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="800" height="800" viewBox="0 0 640 640"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="{light}"/><stop offset="1" stop-color="{bg}"/></linearGradient><linearGradient id="glass"><stop stop-color="#fff" stop-opacity=".95"/><stop offset=".2" stop-color="#f8faf8" stop-opacity=".75"/><stop offset=".7" stop-color="#d2d8d0" stop-opacity=".9"/><stop offset=".88" stop-color="#fff" stop-opacity=".9"/><stop offset="1" stop-color="#bfc8bf"/></linearGradient><linearGradient id="cap" x2="0" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#d8ded8"/></linearGradient><filter id="shadow" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="14"/></filter><filter id="soft"><feGaussianBlur stdDeviation="3"/></filter></defs><rect width="640" height="640" fill="url(#bg)"/><circle cx="590" cy="65" r="255" fill="white" opacity=".12"/><path d="M0 475 Q310 420 640 478 V640 H0Z" fill="{bg}" opacity=".27"/><ellipse cx="340" cy="483" rx="120" ry="19" fill="{ink}" opacity=".19" filter="url(#shadow)"/><g transform="rotate(-11 320 320)"><rect x="232" y="{bodyy}" width="176" height="{bodyh}" rx="{29 if bottle else 21}" fill="url(#glass)" stroke="white" stroke-opacity=".7" stroke-width="2"/><rect x="241" y="{capy}" width="158" height="{64 if bottle else 58}" rx="9" fill="url(#cap)"/><path d="M249 {capy+10} H390" stroke="white" stroke-width="3"/><path d="M254 {capy+18}v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30 m9-30v30" stroke="#c5ccc5" stroke-width="2" opacity=".5"/><rect x="232" y="265" width="176" height="139" fill="{light}"/><rect x="232" y="265" width="176" height="6" fill="{ink}"/><text x="251" y="299" font-family="Arial,sans-serif" font-size="23" font-weight="600" fill="#242622">Logo</text><text x="251" y="333" font-family="Arial,sans-serif" font-size="{12 if len(name)>11 else 14}" font-weight="700" letter-spacing="1.2" fill="{ink}">{name}</text><text x="251" y="353" font-family="Arial,sans-serif" font-size="10" fill="#555d55">{desc}</text><path d="M251 368 H386" stroke="{ink}" opacity=".25"/><text x="251" y="388" font-family="Arial,sans-serif" font-size="8" letter-spacing="1" fill="#616961">PERSONALIZED FOR YOU</text><path d="M245 {bodyy+18}v37" stroke="white" stroke-width="5" stroke-linecap="round" opacity=".7"/></g></svg>'''
 (out/f'{handle}.svg').write_text(svg)
print('Created six original product SVGs')
